import hashlib,json,subprocess,urllib.request
from pathlib import Path
P=Path(__file__).resolve().parent;R=P.parents[2];entry=json.loads((P/'entry.json').read_text());prefix=str(P.relative_to(R))+'/'
changed=[name for name,digest in entry['hashes'].items() if not name.startswith(prefix) and (not (R/name).is_file() or hashlib.sha256((R/name).read_bytes()).hexdigest()!=digest)];assert not changed,changed
head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=R).decode().strip();branch=subprocess.check_output(['git','branch','--show-current'],cwd=R).decode().strip();assert head==entry['head'] and branch==entry['branch'];assert [x for x in (R/'docs/task33/implementation-status.md').read_text().splitlines() if x.startswith('active_run:')]==['active_run: NONE']
O=P.parent/'offer-qa03-fix-2026-10-13-r1';server=json.loads((O/'server.json').read_text());assert server['script'].encode() in Path('/proc/'+str(server['pid'])+'/cmdline').read_bytes();receipt=json.load(urllib.request.urlopen(server['url']+'/qa/start-version/',timeout=10));assert receipt['testing'] and receipt['entry_matches_startup'] and receipt['startup_matches_disk'];(P/'runtime-receipt-final.json').write_text(json.dumps(receipt,indent=2))
base=json.loads((P/'browser.result.json').read_text());diagnostic=json.loads((P/'diagnostic.result.json').read_text());prototype=json.loads((P/'prototype.result.json').read_text());assert all(not d.get('error') and not d['errors'] for d in [base,diagnostic,prototype]);assert len(base['rows'])==27 and sum(r['status']=='FAIL' for r in base['rows'])==17;assert len(diagnostic['rows'])==3 and all(r['status']=='FAIL' for r in diagnostic['rows']);assert len(prototype['rows'])==3 and all(r['status']=='PASS' for r in prototype['rows'])
pngs=[{'file':str(f.relative_to(P)),'bytes':f.stat().st_size,'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'kind':'prototype-only' if 'prototype' in f.name else 'baseline'} for f in sorted((P/'screenshots').glob('*.png'))];assert len(pngs)==15;(P/'png-manifest.json').write_text(json.dumps(pngs,indent=2))
assert json.loads((P/'readonly-readback.command.json').read_text())['exit']==0
verification={'checkout':str(R),'head':head,'branch':branch,'active_run':'NONE','incoming_files_unchanged':True,'unexpected_changes':changed,'application_changes':0,'runtime_source_match':True,'baseline_geometry':{'rows':27,'FAIL':17,'PASS':10},'exact_table_diagnostic_FAIL':3,'temporary_browser_prototype_PASS':3,'prototype_is_application_acceptance':False,'baseline_png':12,'prototype_png':3,'readonly_baseline_preserved':True,'implementation':'NOT RUN','full_module05':'NOT RUN','production':'NOT RUN','git_mutations':False,'finding':'OFFER-QA-04 OPEN'};(P/'verification.json').write_text(json.dumps(verification,indent=2));print(json.dumps(verification))
